    mCcCyl.SetStts(&mCcStts);
    f32 tempVar1 = (f32)getHeight();
    f32 tempVar2 = (f32)getR();
    if (scale.x > 1.0f) {
        tempVar1 *= scale.x;
        tempVar2 *= scale.x;
    }
    mCcCyl.SetR(tempVar2);
    mCcCyl.SetH(tempVar1);
