    mAcch.Set(fopAcM_GetPosition_p(this), fopAcM_GetOldPosition_p(this), this, 1, &mAcchCir, fopAcM_GetSpeed_p(this), NULL, NULL);

    field_0x644 = daSpcItem01_prm::getFlag(this);
    fopAcM_SetGravity(this, -4.0f);
