/* 8015E11C-8015E20C       .text move__13daSpcItem01_cFv */
void daSpcItem01_c::move() {
    fopAcM_posMoveF(this, mCcStts.GetCCMoveP());  // §327 mStts -> mCcStts
    mAcch.CrrPos(dComIfG_Bgsp());                 // §327 reference form (toripost recipe)
    switch (m_itemNo) {
    case WWITEM_SHIELD_e:
        break;
    case WWITEM_JOY_PENDANT_e:
        if (mAcch.ChkGroundLanding()) {
            speed.x = 0.0f;
            speed.y = 0.0f;
            speed.z = 0.0f;
            speedF = 0.0f;
        }
        break;
    default:
        if (mAcch.ChkGroundLanding()) {
            field_0x642 += 1;
            f32 newGravity = field_0x63C * 0.62f;
            if (newGravity > gravity - 0.5f) {
                speedF = 0.0f;
            } else {
                speed.x = 0.0f;
                speed.y = -newGravity;
                speed.z = 0.0f;
            }
        }
        break;
    }

    if (speed.y != 0.0f) {
        field_0x63C = speed.y;
    }
}

/* 8015E20C-8015E278       .text rotate_item__13daSpcItem01_cFv */
void daSpcItem01_c::rotate_item() {
    if (isRupee(m_itemNo)) {
        if (field_0x642 == 0) {
            field_0x640 = current.angle.x + 0x2000;
        } else {
            field_0x640 = 0;
        }
        cLib_chaseAngleS(&current.angle.x, field_0x640, 0x2000);
    }
}

